from __future__ import annotations
from typing import TypeVar
from robot.libraries.BuiltIn import BuiltIn, RobotNotRunningError  # type: ignore

T = TypeVar("T", str, bool, None)


def get_robot_variable(param: str, default: T) -> T:
    """
    Get variable from robot session.
    :param [str] param: Name of parameter that should be retrieved from robot
    :param str | bool | None default: Value that should be returned if parameter cannot be returned
    :return str: Value retrieved from robot or default if provided
    :raise [RobotNotRunningError]: Exception from robot if not running and default not provided
    """
    try:
        return BuiltIn().get_variable_value("${%s}" % param)
    except RobotNotRunningError:
        if default is not None:
            return default
        raise
